package sfz.msg.l11.demo

import org.apache.kafka.clients.admin.Admin
import org.apache.kafka.clients.admin.AlterConfigOp
import org.apache.kafka.clients.admin.ConfigEntry
import org.apache.kafka.clients.admin.NewTopic
import org.apache.kafka.clients.consumer.ConsumerRecords
import org.apache.kafka.clients.consumer.KafkaConsumer
import org.apache.kafka.clients.consumer.KafkaShareConsumer
import org.apache.kafka.clients.producer.KafkaProducer
import org.apache.kafka.clients.producer.ProducerRecord
import org.apache.kafka.common.config.ConfigResource
import org.apache.kafka.common.serialization.StringDeserializer
import org.apache.kafka.common.serialization.StringSerializer
import java.time.Duration
import java.util.Collections
import java.util.concurrent.atomic.AtomicBoolean
import java.util.concurrent.atomic.AtomicInteger
import kotlin.concurrent.thread

private const val BOOTSTRAP = "localhost:9092"
private val running = AtomicBoolean(true)

/**
 * Twelve notifications in a topic with ONE partition, read by three members of a consumer group and, at the same
 * time, by three members of a share group. Each member takes 100 ms per record, as if it called an SMS provider.
 */
fun main() {
    val run = System.currentTimeMillis() % 100_000
    val topic = "notifications-$run"
    val consumerGroup = "notify-cg-$run"
    val shareGroup = "notify-sg-$run"
    Admin.create(mapOf<String, Any>("bootstrap.servers" to BOOTSTRAP)).use { admin ->
        admin.createTopics(listOf(NewTopic(topic, 1, 1.toShort()))).all().get()
        // a share group reads its settings from group configs; start at the beginning instead of the default, latest
        val reset = AlterConfigOp(ConfigEntry("share.auto.offset.reset", "earliest"), AlterConfigOp.OpType.SET)
        admin.incrementalAlterConfigs(mapOf(ConfigResource(ConfigResource.Type.GROUP, shareGroup) to listOf(reset))).all().get()

        val got = (1..3).flatMap { listOf("c$it", "s$it") }.associateWith { Collections.synchronizedList(mutableListOf<Long>()) }
        val cgCount = AtomicInteger()
        val sgCount = AtomicInteger()
        val members = (1..3).flatMap { i ->
            listOf(
                thread { groupMember(topic, consumerGroup, "c$i", got.getValue("c$i"), cgCount) },
                thread { shareMember(topic, shareGroup, "s$i", got.getValue("s$i"), sgCount) },
            )
        }
        awaitMembers(admin, consumerGroup, shareGroup)
        KafkaProducer(mapOf<String, Any>("bootstrap.servers" to BOOTSTRAP), StringSerializer(), StringSerializer()).use { p ->
            repeat(12) { p.send(ProducerRecord(topic, 0, "acct-$it", "notify-$it")).get() }
        }
        val deadline = System.nanoTime() + 60_000_000_000L
        while ((cgCount.get() < 12 || sgCount.get() < 12) && System.nanoTime() < deadline) Thread.sleep(100)
        running.set(false)
        members.forEach { it.join() }
        println("consumer group: c1 got ${got["c1"]}, c2 got ${got["c2"]}, c3 got ${got["c3"]}")
        println("share group:    s1 got ${got["s1"]}, s2 got ${got["s2"]}, s3 got ${got["s3"]}")
    }
}

private fun groupMember(topic: String, group: String, name: String, got: MutableList<Long>, total: AtomicInteger) =
    KafkaConsumer(mapOf<String, Any>("bootstrap.servers" to BOOTSTRAP, "group.id" to group, "group.protocol" to "consumer",
        "auto.offset.reset" to "earliest", "client.id" to name), StringDeserializer(), StringDeserializer()).use { c ->
        c.subscribe(listOf(topic))
        while (running.get()) handle(c.poll(Duration.ofMillis(200)), got, total)
    }

private fun shareMember(topic: String, group: String, name: String, got: MutableList<Long>, total: AtomicInteger) =
    KafkaShareConsumer(mapOf<String, Any>("bootstrap.servers" to BOOTSTRAP, "group.id" to group, "client.id" to name,
        "max.poll.records" to 2, "share.acquire.mode" to "record_limit"), StringDeserializer(), StringDeserializer()).use { c ->
        c.subscribe(listOf(topic))
        while (running.get()) handle(c.poll(Duration.ofMillis(200)), got, total) // implicit mode: the next poll accepts
    }

private fun handle(records: ConsumerRecords<String, String>, got: MutableList<Long>, total: AtomicInteger) {
    for (r in records) {
        Thread.sleep(100) // send the SMS
        got += r.offset()
        total.incrementAndGet()
    }
}

/** Waits until both groups have their three members, so that no member starts with a head start. */
private fun awaitMembers(admin: Admin, consumerGroup: String, shareGroup: String) {
    val deadline = System.nanoTime() + 60_000_000_000L
    while (System.nanoTime() < deadline) {
        try {
            val cg = admin.describeConsumerGroups(listOf(consumerGroup)).all().get().getValue(consumerGroup).members().size
            val sg = admin.describeShareGroups(listOf(shareGroup)).all().get().getValue(shareGroup).members().size
            if (cg == 3 && sg == 3) return
        } catch (e: Exception) {
            // the groups don't exist yet
        }
        Thread.sleep(200)
    }
}

sections.body:
How can three members read one partition and never get the same record? The broker keeps a state for every record it hands out. For each partition a share group reads, it tracks the in-flight records, the ones not finished yet, starting at the share-partition start offset (SPSO). Every record before the SPSO is finished. Each in-flight record is in one of four states:

- available: waiting for a member;
- acquired: handed to one member, under a lock that runs out after `share.record.lock.duration.ms` (30 seconds by default);
- acknowledged: done;
- archived: given up on, never delivered again.

A poll acquires available records for that member, and each acquisition adds one to the record's **delivery count**. The member then answers for each record with one of four acknowledgement types. ACCEPT means done. RELEASE gives the record back for another try, for a failure that may pass, such as a timeout at the texting company. REJECT archives it, for a failure that won't pass, such as an invalid phone number. RENEW (Kafka 4.2, KIP-1222) makes the lock last longer, for a slow record.

If the member dies or freezes, nobody answers, the lock runs out, and the record becomes available to anyone. The group doesn't have to notice first that the member is gone. In the kitchen, a cook who takes a slip has 30 seconds to say how it went. If they wander off, the slip goes back on the rail for anyone.

Here is the loop with an answer for every record, in Java and then in Kotlin:

```java
// share.acknowledgement.mode=explicit: every record gets its own answer
for (ConsumerRecord<String, String> r : consumer.poll(Duration.ofMillis(500))) {
    try {
        sms.send(r.value());
        consumer.acknowledge(r, AcknowledgeType.ACCEPT);      // done
    } catch (ProviderTimeout e) {
        consumer.acknowledge(r, AcknowledgeType.RELEASE);     // transient: try again, maybe on another member
    } catch (InvalidPhoneNumber e) {
        consumer.acknowledge(r, AcknowledgeType.REJECT);      // permanent: archive it (and DLQ it, in 4.4)
    }
}
consumer.commitSync();                                         // send the acknowledgements to the broker
```

```kotlin
// share.acknowledgement.mode=explicit: every record gets its own answer
for (r in consumer.poll(Duration.ofMillis(500))) {
    val ack = try {
        sms.send(r.value())
        AcknowledgeType.ACCEPT                                 // done
    } catch (e: ProviderTimeout) {
        AcknowledgeType.RELEASE                                // transient: try again, maybe on another member
    } catch (e: InvalidPhoneNumber) {
        AcknowledgeType.REJECT                                 // permanent: archive it (and DLQ it, in 4.4)
    }
    consumer.acknowledge(r, ack)
}
consumer.commitSync()                                          // send the acknowledgements to the broker
```

That loop runs in explicit mode (`share.acknowledgement.mode=explicit`). In the default, implicit mode, the next `poll` accepts the whole previous batch, every record the last poll returned.

A record can't bounce forever. Once its delivery count reaches `share.delivery.count.limit` (5 by default), the next release or expired lock archives it. Since Kafka 4.4 (KIP-1191, with the feature `share.version` at 2), the broker can also copy an archived record to a dead-letter topic. That's a topic that collects records that failed too often. The group setting `errors.deadletterqueue.topic.name` names it. The broker writes the record's origin and delivery count as headers, small labels attached to a record, and the record itself only with `errors.deadletterqueue.copy.record.enable=true`. By default the topic's name must start with `dlq.`, and the topic needs `errors.deadletterqueue.group.enable=true`. The feature is new, and Confluent, a company that sells Kafka services, warns that it may still change in a minor release.

Share groups take most settings from group configs, set with `kafka-configs.sh --entity-type groups` or the Admin client, Kafka's library for managing it from code. The broker keeps them within bounds: the lock between 15 and 60 seconds, the delivery limit between 2 and 10. `share.auto.offset.reset` is `latest` by default, so a new group skips what's already in the topic. Set it to `earliest` before the first member joins if you want the backlog.

What you give up is order. Records of one batch arrive in offset order, but members work in parallel and redeliveries come back later. So there's no order per key, and none per partition. **A share group promises each record to one member, not an order. Use it for work items that stand alone, never for a ledger.** Next, we'll hold it up against the queue it imitates.

